import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"ADR-0009: 为什么通知系统与恢复引擎解耦","description":"","frontmatter":{},"headers":[],"relativePath":"zh/adr/ADR-0009-why-notification-decoupled.md","filePath":"zh/adr/ADR-0009-why-notification-decoupled.md","lastUpdated":0}`),a={name:`zh/adr/ADR-0009-why-notification-decoupled.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="adr-0009-为什么通知系统与恢复引擎解耦" tabindex="-1">ADR-0009: 为什么通知系统与恢复引擎解耦 <a class="header-anchor" href="#adr-0009-为什么通知系统与恢复引擎解耦" aria-label="Permalink to “ADR-0009: 为什么通知系统与恢复引擎解耦”">​</a></h1><ul><li>状态：已接受</li><li>日期：2026-10-31</li><li>关联：docs/guide/notification.md §8</li></ul><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to “背景”">​</a></h2><p>通知渠道（Webhook/SMTP/herald）依赖网络与第三方可用性；恢复引擎依赖本地资源。 耦合两者意味着：断网时恢复被发送卡住；渠道故障放大成系统故障； <code>delivery_failed</code> 再触发通知会无限自激。</p><h2 id="决策" tabindex="-1">决策 <a class="header-anchor" href="#决策" aria-label="Permalink to “决策”">​</a></h2><p>Core Engine 只产生结构化 <code>NotificationEvent</code>（11 种类型，custos-model）， 经 EventEmitter 回调交给 custos-notify；通知引擎负责规则匹配、入队 （SQLite 五状态队列）、后台投递、指数退避、死信、去重聚合； 入队与发送<strong>永不阻塞</strong>恢复（§8.1 验收）；<code>notification.delivery_failed</code> 只落本地日志，构造性断开自激环。持久化经 <code>NotificationQueue</code> port trait， notify 不反向依赖 store/engine，依赖图无环。</p><h2 id="替代方案" tabindex="-1">替代方案 <a class="header-anchor" href="#替代方案" aria-label="Permalink to “替代方案”">​</a></h2><ul><li><strong>恢复引擎内联发送</strong>：渠道慢即恢复慢；渠道崩即恢复崩；无法离线补发。</li><li><strong>共享线程池直发</strong>：无持久化，断网丢事件；无重试语义。</li></ul><h2 id="优缺点" tabindex="-1">优缺点 <a class="header-anchor" href="#优缺点" aria-label="Permalink to “优缺点”">​</a></h2><p>优点：断网期间事件全部留队、恢复后补发（验收测试 offline.rs）； 渠道可插拔（local-log/webhook/smtp/herald 同一 Channel trait）； 敏感信息治理（scrub）在一处集中执行。 缺点：多一层队列状态机（Pending/Sending/Delivered/RetryScheduled/DeadLetter）； 端到端只有 at-least-once，依赖稳定事件 id + 接收方去重。</p><h2 id="后续影响" tabindex="-1">后续影响 <a class="header-anchor" href="#后续影响" aria-label="Permalink to “后续影响”">​</a></h2><ul><li>Webhook/SMTP/herald 渠道按此 trait 增补；新渠道不触碰核心。</li><li>CLI <code>notify status/retry</code> 读队列；恢复与通知的验收门分离。</li></ul>`,12)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};